/** Bubble sort: adjacent swaps; O(n^2) time and O(1) extra space. */
import java.util.*;
public class BubbleSort {static void sort(int[]a){for(int i=0;i<a.length;i++){boolean swapped=false;for(int j=0;j<a.length-i-1;j++)if(a[j]>a[j+1]){int t=a[j];a[j]=a[j+1];a[j+1]=t;swapped=true;}if(!swapped)break;}}public static void main(String[]args){Scanner sc=new Scanner(System.in);System.out.print("Array size: ");int n=sc.nextInt();if(n<0){System.out.println("Invalid size");sc.close();return;}int[]a=new int[n];System.out.println("Enter elements:");for(int i=0;i<n;i++)a[i]=sc.nextInt();sort(a);System.out.println(Arrays.toString(a));sc.close();}}